  drawTrees(now){const ctx=this.ctx,scale=this.scale();for(const tree of this.state.trees){if(!this.isVisible(tree.x,tree.y,7))continue;const p=this.worldToScreen(tree.x,tree.y),fruit=FRUIT_BY_ID[tree.fruit]||FRUIT_BY_ID.apple,ripe=["ripe","golden"].includes(tree.status);ctx.save();ctx.strokeStyle="#6e4f2f";ctx.lineWidth=clamp(scale*.7,3,8);ctx.beginPath();ctx.moveTo(p.x,p.y+scale*1.5);ctx.lineTo(p.x,p.y-scale*2);ctx.stroke();const crown=ctx.createRadialGradient(p.x-scale,p.y-scale*2.8,1,p.x,p.y-scale*2.5,scale*3.4);crown.addColorStop(0,tree.diseased?"#c9ae63":tree.golden?"#ffdc43":"#7fca56");crown.addColorStop(1,tree.diseased?"#887241":"#357d42");ctx.fillStyle=crown;ctx.beginPath();ctx.arc(p.x,p.y-scale*2.5,clamp(scale*2.9,15,34),0,Math.PI*2);ctx.fill();if(ripe)for(let i=0;i<4;i++){const angle=i*1.7+(tree.harvests||0),radius=scale*1.55;ctx.font=`${clamp(scale*1.6,10,18)}px system-ui`;ctx.fillText(tree.golden?"🌟":fruit.icon,p.x+Math.cos(angle)*radius,p.y-scale*2.4+Math.sin(angle)*radius*.65);}if(!ripe){const remaining=Math.max(0,(tree.readyAt-now)/1000),ratio=1-clamp(remaining/(fruit.growthSeconds||30),0,1);ctx.fillStyle="rgba(255,255,255,.75)";ctx.fillRect(p.x-scale*2,p.y+scale*2.3,scale*4,3);ctx.fillStyle="#84cf52";ctx.fillRect(p.x-scale*2,p.y+scale*2.3,scale*4*ratio,3);}if(distance(this.player,tree)<4){ctx.fillStyle="#fff";ctx.font="800 8px system-ui";ctx.textAlign="center";ctx.fillText(ripe?"PICK":"INSPECT",p.x,p.y-scale*6);}ctx.restore();this.entities.push({type:"tree",id:tree.id,x:tree.x,y:tree.y,radius:3,label:`${fruit.name} tree`});}}
