  updatePrompt(){const nearest=[...this.entities].sort((a,b)=>distance(this.player,a)-distance(this.player,b))[0],near=nearest&&distance(this.player,nearest)<5;let text=this.state.sewer?.active?"Explore the sewer. Use landmarks—the full maze map only works at its entrance.":"Walk near a tree, building, worker, crate, or road manhole to interact.";if(near)text=nearest.type==="manhole"?(this.state.sewer.entrances[nearest.id].open?"Enter Sewer":"Open manhole"):`Interact: ${nearest.label}`;if(text!==this.lastPrompt){this.lastPrompt=text;this.onPrompt(text);}}
